const currentUser=async(req:any)=>{if(!installation.installed||!installation.available)return null;if('resolvedUser' in req)return req.resolvedUser;const token=String(req.headers.cookie||'').split(';').map((x:string)=>x.trim()).find((x:string)=>x.startsWith('webtv_session='))?.split('=')[1];if(!token||!/^[a-f0-9]{64}$/.test(token))return req.resolvedUser=null;const session=await db.session.findUnique({where:{token},include:{user:{include:{sourceAccess:true,membershipPlan:true}}}});if(!session||session.expiresAt<new Date()||!session.user.enabled){if(session)await db.session.delete({where:{token}});return req.resolvedUser=null}return req.resolvedUser=await membership.hydrate(session.user)};
const requireAccount=async(req:any,res:any)=>{const user=await currentUser(req);if(!user||!user.enabled){res.status(401).json({error:'请先登录'});return null}return user};
// Anonymous visitors resolve to the synthetic guest account (driven by the
// admin-editable guest membership plan) when guest mode is enabled; account-
// bound endpoints keep using requireAccount so guests never own data.
const guestIdentity=async(req:any)=>{if('guestUser' in req)return req.guestUser;try{req.guestUser=await membership.guest()}catch{req.guestUser=null}return req.guestUser};
const requireUser=async(req:any,res:any)=>{const user=await currentUser(req)||await guestIdentity(req);if(!user||!user.enabled){res.status(401).json({error:'请先登录'});return null}return user};
const requireAdmin=async(req:any,res:any)=>{const user=await requireAccount(req,res);if(!user)return null;if(user.role!=='admin'){res.status(403).json({error:'需要管理员权限'});return null}return user};
