// Central API gate runs before every content/configuration route, including legacy endpoints.
app.use('/api',async(req:any,res:any,next:any)=>{
  let route:string;try{route=decodeURIComponent(req.originalUrl.split('?')[0]).toLowerCase()}catch{return res.status(400).json({error:'无效路径'})}
  if(req.headers.origin){
    if(!trustedBrowserOrigin(req.headers.origin,req.get('host')))return res.status(403).json({error:'请求来源不受信任'});
  }
  await installation.ready;
  const bootstrapRoute=['/api/health','/api/install','/api/install/status','/api/install/database/test','/api/auth/me'].includes(route)||route==='/api/settings'&&req.method==='GET';
  if(!bootstrapRoute&&(!installation.installed||!installation.available))return res.status(503).json({error:'请先完成安装，或检查数据库连接'});
  if(route==='/api/auth/login'){
    const key=`${req.ip}:${String(req.body?.username||'').slice(0,32).toLowerCase()}`;let count=loginAttempts.get(key);
    if(!count||count.at+900000<Date.now()){if(loginAttempts.size>5000)loginAttempts.clear();count={at:Date.now(),count:0};loginAttempts.set(key,count)}
    if(++count.count>15)return res.status(429).json({error:'登录尝试过多，请15分钟后重试'});
  }
  if(['/api/health','/api/install','/api/install/status','/api/install/database/test','/api/auth/me','/api/auth/login','/api/auth/logout','/api/auth/register'].includes(route)||route==='/api/settings'&&req.method==='GET')return next();
  const user=await requireUser(req,res);if(!user)return;req.authUser=user;
  res.setHeader('Cache-Control','private, no-store');res.setHeader('Vary','Cookie');
  if(/^\/api\/(admin|config)(\/|$)/.test(route)||route==='/api/settings'&&req.method!=='GET'){
    if(user.guest)return res.status(401).json({error:'请先登录'});
    if(user.role!=='admin')return res.status(403).json({error:'需要管理员权限'});
  }
  const permission=permissionForApi(route,req.method);
  if(permission&&user.role!=='admin'&&!user.permissions.includes(permission))return res.status(403).json({error:`当前会员没有「${permissionLabels[permission]}」权限`,code:'MEMBERSHIP_REQUIRED',permission});
  if(route==='/api/ai/chat'&&req.body?.mode==='recommend'&&user.role!=='admin'&&!user.permissions.includes('recommendations'))return res.status(403).json({error:'当前会员没有「个性化推荐」权限',code:'MEMBERSHIP_REQUIRED',permission:'recommendations'});
  if(user.role!=='admin'&&route==='/api/library/videos'&&req.query.q&&!user.permissions.includes('search'))return res.status(403).json({error:'当前会员没有搜索权限'});
  if(['POST','PUT'].includes(req.method)&&/^\/api\/(favorites|history|danmaku|playback-errors)(\/|$)/.test(route)){
    const key=String(req.body?.sourceKey||'');if(!key||!canSource(user,key)||!await db.source.findFirst({where:{key,enabled:true}}))return res.status(403).json({error:'数据源不可用或未授权'});
  }
  if(req.method==='GET'&&!/^\/api\/(admin|auth|membership|profile|install|settings|config|access|health)(\/|$)/.test(route)){
    const sendJson=res.json.bind(res);
    res.json=(body:any)=>{
      // Attribution is optional decoration: a failure must not block playback.
      void virtualUploaders.enrich(body).then(sendJson,()=>sendJson(body));
      return res;
    };
  }
  next();
});
