const categoryAliases:Record<string,string>={'国漫':'动漫','国产动画':'动漫','国产动漫':'动漫','番剧':'动漫','动画片':'动漫','大陆剧':'国产剧','国产电视剧':'国产剧','内地剧':'国产剧','香港剧':'港剧','台湾剧':'台剧','美剧':'欧美剧','英剧':'欧美剧','韩剧':'日韩剧','日剧':'日韩剧','综艺节目':'综艺','真人秀':'综艺','脱口秀':'综艺','电影片':'电影','动作片':'动作','喜剧片':'喜剧','爱情片':'爱情','科幻片':'科幻','恐怖片':'恐怖','剧情片':'剧情','悬疑片':'悬疑','犯罪片':'犯罪','战争片':'战争','纪录片':'纪录片','短剧片':'短剧'};
const guessLocalCategory=(remote:string,locals:string[])=>{const raw=String(remote||'').trim(),alias=categoryAliases[raw]||categoryAliases[normalizeCategory(raw)]||raw,a=normalizeCategory(alias);const exact=locals.find(x=>normalizeCategory(x)===a);if(exact)return exact;return locals.find(x=>a.length>=2&&(a.includes(normalizeCategory(x))||normalizeCategory(x).includes(a)))||''};
const findBoundCategory=(remote:string,mapped:Map<string,string>)=>{const direct=mapped.get(remote);if(direct)return direct;const a=normalizeCategory(remote);return [...mapped.entries()].find(([key])=>{const b=normalizeCategory(key);return b===a||(a.length>=2&&(a.includes(b)||b.includes(a)))})?.[1]||''};
type CacheEntry={value:any;expires:number};
const responseCache=new Map<string,CacheEntry>();
const inflightRequests=new Map<string,Promise<any>>();
async function cached<T>(key:string,ttl:number,loader:()=>Promise<T>):Promise<T>{const hit=responseCache.get(key);if(hit&&hit.expires>Date.now())return hit.value as T;const running=inflightRequests.get(key);if(running)return running as Promise<T>;const promise=loader().then(value=>{if(responseCache.size>500)responseCache.delete(responseCache.keys().next().value as string);responseCache.set(key,{value,expires:Date.now()+ttl});return value}).finally(()=>inflightRequests.delete(key));inflightRequests.set(key,promise);return promise}
async function fetchText(url:string,timeout=7000){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeout);try{const response=await fetch(url,{signal:controller.signal,headers:{Accept:'application/json, application/xml, text/xml;q=0.9, */*;q=0.8'}});if(!response.ok)throw new Error(`远程源 HTTP ${response.status}`);return await response.text()}finally{clearTimeout(timer)}}
type JsonVideo={vod_id?:string|number;vod_name?:string;vod_pic?:string;vod_year?:string|number;vod_class?:string;type_id?:string|number;type_pid?:string|number;type_name?:string;vod_area?:string;vod_lang?:string;vod_tag?:string;vod_content?:string;vod_director?:string;vod_actor?:string;vod_play_url?:string;vod_play_from?:string};
const xmlValue=(xml:string,tag:string)=>{const m=xml.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`,'i')); return (m?.[1]||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/<[^>]+>/g,'').trim()};
const xmlPlays=(xml:string)=>[...xml.matchAll(/<dd[^>]*>([\s\S]*?)<\/dd>/gi)].map(m=>(m[1]||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').trim()).filter(Boolean).join('$$$');
const xmlPlayFlags=(xml:string)=>[...xml.matchAll(/<dd[^>]*flag=["']([^"']+)["'][^>]*>/gi)].map(m=>m[1]).filter(Boolean).join('$$$');
const asVideo=(x:any):JsonVideo=>({vod_id:x.vod_id??x.id,vod_name:x.vod_name??x.name,vod_pic:x.vod_pic??x.pic,vod_year:x.vod_year??x.year,vod_class:x.vod_class??x.type_name??x.type,type_name:x.type_name??x.type,type_id:x.type_id,type_pid:x.type_pid,vod_area:x.vod_area??x.area,vod_lang:x.vod_lang??x.lang,vod_tag:x.vod_tag??x.tag,vod_content:x.vod_content??x.des??x.note,vod_director:x.vod_director??x.director,vod_actor:x.vod_actor??x.actor,vod_play_url:x.vod_play_url??x.playurl,vod_play_from:x.vod_play_from??x.playfrom});
const parseRemote=(text:string)=>{let raw:any={};let list:JsonVideo[]=[];try{raw=JSON.parse(text);const payload=Array.isArray(raw)?raw:Array.isArray(raw.list)?raw.list:Array.isArray(raw.data)?raw.data:Array.isArray(raw.data?.list)?raw.data.list:Array.isArray(raw.vod)?raw.vod:[];list=payload.map(asVideo).filter((x:JsonVideo)=>Boolean(x.vod_name))}catch{const blocks=[...text.matchAll(/<video[\s\S]*?<\/video>/gi)].map(m=>m[0]);list=blocks.map(block=>asVideo({id:xmlValue(block,'id'),name:xmlValue(block,'name'),pic:xmlValue(block,'pic'),year:xmlValue(block,'year'),type:xmlValue(block,'type'),type_id:xmlValue(block,'tid'),area:xmlValue(block,'area'),lang:xmlValue(block,'lang'),des:xmlValue(block,'des')||xmlValue(block,'note'),director:xmlValue(block,'director'),actor:xmlValue(block,'actor'),playurl:xmlValue(block,'vod_play_url')||xmlValue(block,'playurl'),playfrom:xmlValue(block,'vod_play_from')||xmlValue(block,'playfrom')})).filter(x=>x.vod_name)}return {raw,list:[...new Map(list.map(x=>[String(x.vod_id||x.vod_name),x])).values()],total:Number(raw.total||raw.recordcount||raw.data?.total||text.match(/recordcount=["'](\d+)["']/i)?.[1]||list.length)}};
async function remoteList(source:any,currentPage=1,pageSize=40,keyword='',hydrate=false,typeId=''){if(source.type!=='tvbox-json'||!source.api?.startsWith('http'))return {raw:{},list:[],total:0};const u=new URL(source.api);u.searchParams.set('ac','list');u.searchParams.set('pg',String(currentPage));u.searchParams.set('pagesize',String(pageSize));if(keyword)u.searchParams.set('wd',keyword);if(typeId)u.searchParams.set('t',typeId);const key=`list:${source.key}:${u.toString()}:${hydrate}`;return cached(key,keyword?45000:120000,async()=>{const result=parseRemote(await fetchText(u.toString()));if(!hydrate)return result;const list=await Promise.all(result.list.map(async item=>{if(item.vod_pic||!item.vod_id)return item;try{const detail=await remoteDetail(source,`${source.key}:${String(item.vod_id)}`);return detail?{...item,vod_pic:detail.vod_pic}:item}catch{return item}}));return {...result,list}})}
const categoryTextMatches=(value:string,category:string)=>{const text=String(value||'');if(category==='动漫')return /动漫|动画|番剧|里番/.test(text);if(category==='电视剧')return /剧|电视剧/.test(text)&&!/综艺/.test(text);if(category==='电影')return /电影|片/.test(text)&&!/动漫|动画/.test(text);return text===category};
const remoteCategoryClasses=async(source:any)=>{if(source.type!=='tvbox-json'||!source.api?.startsWith('http'))return [];const u=new URL(source.api);u.searchParams.set('ac','list');u.searchParams.set('pg','1');u.searchParams.set('pagesize','1');const result=await cached(`classes:${source.key}`,600000,async()=>{const body=await fetchText(u.toString());return body.trimStart().startsWith('<')?{raw:{class:xmlCategories(body).map(row=>({type_id:row.id,type_pid:row.parent,type_name:row.name}))}}:parseRemote(body)});return Array.isArray(result.raw?.class||result.raw?.data?.class)?(result.raw.class||result.raw.data.class).map((x:any)=>({id:String(x.type_id||''),parent:String(x.type_pid||''),name:String(x.type_name||'')})).filter((x:any)=>x.id&&x.name):[];};
const remoteCategoryTypeIds=async(source:any,category:string)=>{const classes=await remoteCategoryClasses(source);const matched=classes.filter((x:any)=>categoryTextMatches(x.name,category));const leaf=matched.filter((x:any)=>!matched.some((other:any)=>other.parent===x.id&&other.id!==x.id));return (leaf.length?leaf:matched).map((x:any)=>x.id);};
const makeEpisodes=(detail:JsonVideo,sourceKey:string)=>String(detail.vod_play_url||'').split('$$$').flatMap((line,i)=>line.split('#').map((part,j)=>{const [name,urlPart]=part.split('$');const url=String(urlPart||name||'');return {id:`${sourceKey}:${String(detail.vod_id)}:${i}:${j}`,videoId:`${sourceKey}:${String(detail.vod_id)}`,lineName:String(String(detail.vod_play_from||'默认线路').split('$$$')[i]||'默认线路'),name:name||`第 ${j+1} 集`,url,type:url.includes('.m3u8')?'m3u8':'mp4',sortOrder:i*100+j}})).filter(x=>x.url);
async function remoteDetail(source:any,id:string){const remoteId=id.split(':').slice(1).join(':');if(!remoteId||!source.api?.startsWith('http'))return null;return cached(`detail:${source.key}:${remoteId}`,600000,async()=>{const u=new URL(source.api);u.searchParams.set('ac','detail');u.searchParams.set('ids',remoteId);const text=await fetchText(u.toString(),10000);let detail:JsonVideo|undefined;if(text.trimStart().startsWith('<')){const block=text.match(/<video[\s\S]*?<\/video>/i)?.[0]||text;detail=asVideo({id:remoteId,name:xmlValue(block,'name'),pic:xmlValue(block,'pic'),year:xmlValue(block,'year'),type:xmlValue(block,'type'),type_id:xmlValue(block,'tid'),area:xmlValue(block,'area'),lang:xmlValue(block,'lang'),des:xmlValue(block,'des')||xmlValue(block,'note'),director:xmlValue(block,'director'),actor:xmlValue(block,'actor'),playurl:xmlPlays(block),playfrom:xmlPlayFlags(block)})}else detail=parseRemote(text).list[0];return detail?.vod_name?detail:null})}
const publicVideo=(source:any,x:JsonVideo,full=false)=>({id:`${source.key}:${String(x.vod_id)}`,sourceKey:source.key,sourceName:source.name,title:x.vod_name||'',cover:x.vod_pic,year:Number(x.vod_year)||undefined,category:x.type_name||x.vod_class,originalCategory:x.type_name||x.vod_class,typeId:x.type_id,parentTypeId:x.type_pid,area:x.vod_area,language:x.vod_lang,tags:x.vod_tag,desc:x.vod_content,director:x.vod_director,actors:x.vod_actor,...full?{episodes:makeEpisodes(x,source.key)}:{}});
const localPublic=async(source:any,rows:any[],full=false)=>{const ids=rows.map(x=>x.id);const episodes=full?await db.episode.findMany({where:{videoId:{in:ids}},orderBy:{sortOrder:'asc'}}):[];return rows.map(x=>({...x,id:x.id,sourceKey:source.key,sourceName:source.name,...full?{episodes:episodes.filter(e=>e.videoId===x.id)}:{}}))};
const localList=async(source:any,currentPage=1,pageSize=40,keyword='',filters:any={})=>{const where:any={sourceKey:source.key,visible:true};if(keyword)where.title={contains:keyword};for(const [key,value] of Object.entries(filters))if(value)where[key]={equals:value};const [total,rows]=await Promise.all([db.video.count({where}),db.video.findMany({where,orderBy:{updatedAt:'desc'},skip:(currentPage-1)*pageSize,take:pageSize})]);return {list:await localPublic(source,rows),total}};
