const collectionCancel=new Set<string>();const collectionProgress=new Map<string,{page:number;total:number;processed:number;saved:number;startedAt:number}>();
async function collectSource(source:any,mode='incremental',limit=0){if(collecting.has(source.key))return;collecting.add(source.key);collectionCancel.delete(source.key);collectionProgress.set(source.key,{page:0,total:0,processed:0,saved:0,startedAt:Date.now()});await db.source.update({where:{key:source.key},data:{collectionStatus:'running',collectionError:null,collectedCount:0}});try{const bindings=await db.categoryBinding.findMany({where:{sourceKey:source.key,enabled:true}});if(!bindings.length)throw new Error('请先绑定至少一个采集分类');const mapped=new Map(bindings.map(x=>[x.remoteCategory,x.localCategory]));const pageSize=100;let current=1;let total=0;let saved=0;const requested=Number(limit)||0;const maxItems=requested>0?requested:Number.MAX_SAFE_INTEGER;const maxPages=mode==='all'?Number.MAX_SAFE_INTEGER:1;do{const result=await remoteList(source,current,pageSize);total=result.total;collectionProgress.set(source.key,{page:current,total,processed:saved,saved,startedAt:collectionProgress.get(source.key)?.startedAt||Date.now()});const list=result.list.slice(0,Math.max(0,maxItems-saved));const details=await Promise.all(list.map(async item=>{try{return await remoteDetail(source,`${source.key}:${String(item.vod_id)}`)||item}catch{return item}}));for(let i=0;i<details.length;i++){if(collectionCancel.has(source.key))throw new Error('采集已取消');const item=list[i]!;const detail=details[i]!;const remoteCategory=String(detail.type_name||detail.vod_class||item.type_name||item.vod_class||'').split(/[、,，\/]/)[0].trim();const localCategory=findBoundCategory(remoteCategory,mapped);if(!localCategory)continue;const id=`${source.key}:${String(detail.vod_id||item.vod_id)}`;await db.video.upsert({where:{id},update:{sourceKey:source.key,title:String(detail.vod_name||item.vod_name||''),cover:detail.vod_pic||item.vod_pic||null,year:Number(detail.vod_year||item.vod_year)||null,category:localCategory,originalCategory:remoteCategory,area:detail.vod_area||item.vod_area||null,language:detail.vod_lang||item.vod_lang||null,tags:detail.vod_tag||item.vod_tag||null,desc:detail.vod_content||item.vod_content||null,director:detail.vod_director||item.vod_director||null,actors:detail.vod_actor||item.vod_actor||null},create:{id,sourceKey:source.key,title:String(detail.vod_name||item.vod_name||''),cover:detail.vod_pic||item.vod_pic||null,year:Number(detail.vod_year||item.vod_year)||null,category:localCategory,originalCategory:remoteCategory,area:detail.vod_area||item.vod_area||null,language:detail.vod_lang||item.vod_lang||null,tags:detail.vod_tag||item.vod_tag||null,desc:detail.vod_content||item.vod_content||null,director:detail.vod_director||item.vod_director||null,actors:detail.vod_actor||item.vod_actor||null}});await db.episode.deleteMany({where:{videoId:id}});const eps=makeEpisodes(detail,source.key);if(eps.length)await db.episode.createMany({data:eps.map(e=>({...e,videoId:id}))});saved++;collectionProgress.set(source.key,{page:current,total,processed:saved,saved,startedAt:collectionProgress.get(source.key)?.startedAt||Date.now()})}await db.source.update({where:{key:source.key},data:{collectedCount:saved}});if(mode!=='all'||!list.length||current>=maxPages||saved>=maxItems||current*pageSize>=total)break;current++}while(true);await db.source.update({where:{key:source.key},data:{collectionStatus:'idle',lastCollectedAt:new Date(),collectedCount:saved,collectionError:null}});return {saved,total}}catch(error:any){await db.source.update({where:{key:source.key},data:{collectionStatus:'error',collectionError:String(error?.message||'采集失败').slice(0,300)}});throw error}finally{collecting.delete(source.key);collectionCancel.delete(source.key);setTimeout(()=>collectionProgress.delete(source.key),10000)}}
