app.post('/api/config',async(req,r)=>{try{const raw=String(req.body.rawConfig||'').replace(/^\uFEFF/,'').trim();const c=JSON.parse(raw);if(!Array.isArray(c.sites))return r.status(400).json({error:'配置必须包含 sites 数组'});const valid=c.sites.filter((x:any)=>x.key&&x.name);const keys=valid.map((x:any)=>String(x.key));await db.$transaction(async tx=>{await tx.source.deleteMany({where:{key:{notIn:keys}}});for(const x of valid){const type=typeof x.type==='number'?'tvbox-json':(x.type==='local'?'local':'tvbox-json');const flags={searchable:Boolean(Number(x.searchable??1)),quickSearch:Boolean(Number(x.quickSearch??1)),filterable:Boolean(Number(x.filterable??1))};await tx.source.upsert({where:{key:String(x.key)},update:{name:String(x.name),type,api:String(x.api||x.key),rawConfig:raw,...flags},create:{key:String(x.key),name:String(x.name),type,api:String(x.api||x.key),rawConfig:raw,...flags}})}await tx.setting.upsert({where:{key:'siteName'},update:{value:String(c.name||'大彪TV')},create:{key:'siteName',value:String(c.name||'大彪TV')}})});responseCache.clear();r.json({ok:true,sites:valid.length})}catch{r.status(400).json({error:'JSON 格式无效或配置内容不完整'})}});
app.post('/api/config/import-local',async(_,r)=>{try{const file=path.resolve(process.cwd(),'tvbox.json');if(!existsSync(file))return r.status(404).json({error:'项目根目录没有找到 tvbox.json'});const raw=readFileSync(file,'utf8').replace(/^\uFEFF/,'').trim();const c=JSON.parse(raw);if(!Array.isArray(c.sites))return r.status(400).json({error:'tvbox.json 没有 sites 数组'});const valid=c.sites.filter((x:any)=>x.key&&x.name);const keys=valid.map((x:any)=>String(x.key));await db.$transaction(async tx=>{await tx.source.deleteMany({where:{key:{notIn:keys}}});for(const x of valid){const type=typeof x.type==='number'?'tvbox-json':(x.type==='local'?'local':'tvbox-json');const flags={searchable:Boolean(Number(x.searchable??1)),quickSearch:Boolean(Number(x.quickSearch??1)),filterable:Boolean(Number(x.filterable??1))};await tx.source.upsert({where:{key:String(x.key)},update:{name:String(x.name),type,api:String(x.api||x.key),rawConfig:raw,...flags},create:{key:String(x.key),name:String(x.name),type,api:String(x.api||x.key),rawConfig:raw,...flags}})}await tx.setting.upsert({where:{key:'siteName'},update:{value:String(c.name||'大彪TV')},create:{key:'siteName',value:String(c.name||'大彪TV')}})});responseCache.clear();r.json({ok:true,sites:valid.length,file:'tvbox.json'})}catch{r.status(400).json({error:'tvbox.json 无法读取或格式无效'})}});
