app.get('/api/sources/:key/videos',async(req,r)=>{
  const source=await db.source.findUnique({where:{key:req.params.key}});if(!source)return r.status(404).json({error:'源不存在'});
  let paging;try{paging=readPagination(req.query as Record<string,unknown>,40)}catch(error:any){return r.status(400).json({error:error.message})}
  const {page,pageSize}=paging,category=String(req.query.category||'').trim(),filters={year:String(req.query.year||''),area:String(req.query.area||''),language:String(req.query.language||'')};
  if(await db.video.count({where:{sourceKey:source.key}})){
    const where:any={sourceKey:source.key,visible:true,...category?{category}:{}};
    const candidates=await db.video.findMany({where,orderBy:[{updatedAt:'desc'},{id:'asc'}]});
    const filtered=candidates.filter(item=>matchesFilters(item,filters)),items=await localPublic(source,filtered.slice(paging.offset,paging.offset+pageSize));
    return r.json({items,total:filtered.length,page,pageSize,hasMore:page*pageSize<filtered.length,live:false});
  }
  try{
    const matched=category?await remoteCategoryTypeIds(source,category):[],targets=matched.length?matched:[''];
    const key=JSON.stringify([source.key,source.api,targets,category,filters]),limits=new Map<number,number>();
    const result=await sourcePagination.get(key,targets.length,page,pageSize,async(bucket,upstreamPage)=>{
      const data=await remoteList(source,upstreamPage,20,'',false,targets[bucket]);let limit=limits.get(bucket);
      if(!limit){const first=upstreamPage===1?data:await remoteList(source,1,20,'',false,targets[bucket]);const raw:any=first.raw||{};limit=Number(raw.limit||raw.pagesize||raw.data?.limit||first.list.length||20);limits.set(bucket,limit);}
      return {items:data.list.map(item=>publicVideo(source,item)),hasMore:remoteHasMore(data,upstreamPage,limit)};
    },item=>matchesFilters(item,filters)&&(!category||matched.length>0||categoryTextMatches(String(item.category||''),category)));
    r.json({...result,live:true});
  }catch(error:any){r.status(503).json({error:/页码过深|缩小|繁忙/.test(error.message)?error.message:'远程分页读取失败，请稍后重试'})}
});
