const runScheduledCollection=async()=>{if(!installation.installed||!installation.available)return;const row=await db.setting.findUnique({where:{key:'collectionSchedule'}});let cfg:any={enabled:false,intervalMinutes:1440};try{cfg={...cfg,...JSON.parse(row?.value||'{}')}}catch{}if(!cfg.enabled)return;const now=Date.now(),last=await db.setting.findUnique({where:{key:'collectionScheduleLast'}}),lastAt=last?Date.parse(last.value):0;if(lastAt&&now-lastAt<Number(cfg.intervalMinutes)*60000)return;await db.setting.upsert({where:{key:'collectionScheduleLast'},update:{value:new Date(now).toISOString()},create:{key:'collectionScheduleLast',value:new Date(now).toISOString()}});const sources=await db.source.findMany({where:{enabled:true}});for(const source of sources)if(await db.categoryBinding.count({where:{sourceKey:source.key,enabled:true}})&&!collecting.has(source.key))void collectSource(source,'all',0).catch(()=>{})};setInterval(()=>void runScheduledCollection().catch(()=>{}),30000);
const client=path.resolve(process.cwd(),'client/dist');app.use(express.static(client));app.use((_,r)=>r.sendFile(path.join(client,'index.html')));app.listen(Number(process.env.PORT)||8787,process.env.HOST||'0.0.0.0',()=>console.log(`大彪TV listening on ${process.env.HOST||'0.0.0.0'}:${Number(process.env.PORT)||8787}`));
